// === Tab: mySketch ===
let sceneShader, postShader;
let canvas, fbo, fboNNNB;
var colorTexture, depthTexture;
let crosshatch;

function preload() {
	crosshatch = loadImage("https://openprocessing.org/sketch/2506243/files/crosshatch_texture.png");
}

function setup() {
	canvas = createCanvas(windowHeight*4/3, windowHeight, WEBGL);
	cam = createCamera();
	pixelDensity(1);
	fbo = createFramebuffer();
	fboNNNB = createFramebuffer({
		alpha: false
	});

	rectMode(CENTER);

	sceneShader = createShader(sceneShaderCode.vert, sceneShaderCode.frag);
	shader(sceneShader);
	sceneShader.setUniform("uTexelSize", [1.0 / width, 1.0 / height]);


	postShader = createShader(postShaderCode.vert, postShaderCode.frag);
	shader(postShader);
	postShader.setUniform("uTexelSize", [1.0 / width, 1.0 / height]);
	postShader.setUniform("uOutlineThreshold", 1);
	postShader.setUniform("uLineColor", [0.0, 0.0, 0.0, 1.0]);

	nnnbShader = createShader(nnnbShaderCode.vert, nnnbShaderCode.frag);
	shader(nnnbShader);
	nnnbShader.setUniform("uViewDir", [0, 0, 1]);
	nnnbShader.setUniform("uSmoothness", 0.1);

}

function draw() {
	drawScene(() => {
		////////// DRAW SCENE HERE //////////
		// ortho();
		clear();
		push();
		colorMode(RGB, 1.0);
		noStroke();

		push();
		fill(0.55, 0.67, 0.0);
		translate(0,2000,-5000);
		plane(15000,10000);
		pop();

		push();
		rotateY(frameCount * 0.005);
		fill(0.1, 0.9, 0.4);
		torus(150, 100, 64, 64);


		//translate(300, -200, 0);
		//fill(0.2, 0.9, 0.2);
		//box(150);
		pop();

		push();
		translate(0,-500,-2500);
		fill(0.05, 0.15, 0.2);
		rotateX(PI*0.5);
		plane(15000,5000);
		pop();

		pop();
		/////////////////////////////////////
	});

	clear();
	background(0.5, 0.5, 0.75);

	shader(postShader);
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		postShader.setUniform("uShowDepthMap", 1);
	} else {
		postShader.setUniform("uShowDepthMap", 0);
	}
	postShader.setUniform("uCrossHatchTex", crosshatch);
	postShader.setUniform('uColorTex', fbo.color);
	postShader.setUniform('uDepthTex', fbo.depth);
	postShader.setUniform("uNNNBTex", fboNNNB.color);

	noStroke();
	rect(0, 0, width, -height);
}

function windowResized() {
	canvas.resize(windowHeight*4/3, windowHeight);
	fbo.resize(windowWidth, windowHeight);
	fboNNNB.resize(windowWidth, windowHeight);
	postShader.setUniform("uTexelSize", [1.0 / width, 1.0 / height]);
	sceneShader.setUniform("uTexelSize", [1.0 / width, 1.0 / height]);
}


function generateLightDirFromSphere(x, y, r, w, h) {
	let u = map(x, 0, w, -1, 1);
	let v = map(y, 0, h, -1, 1);
	let vec = createVector(-u, v, 0);
	vec.z = -sqrt(max(0, r * r - u * u - v * v));
	return vec.normalize();
}

function drawScene(func) {
	fbo.begin();
	shader(sceneShader);
	blendMode(REPLACE); // alpha wont affect blending
	sceneShader.setUniform("uSaturation", 0.4);
	sceneShader.setUniform("uSkyGradient", []);
	noLights();
	func();
	fbo.end();


	let lightDir = generateLightDirFromSphere((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0.5, width, height);
	fboNNNB.begin();
	blendMode(REPLACE); // alpha wont affect blending
	shader(nnnbShader);
	directionalLight(255, 255, 255, lightDir);
	func();
	fboNNNB.end();
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: sceneShader ===
let sceneShaderCode = { //Store flat material color
	///////////////////////////////
	vert: `
attribute vec3 aPosition;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

void main(void) {
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);

  gl_Position = uProjectionMatrix * viewModelPosition;
}
	`,
	///////////////////////////////
	frag: `
precision highp float;

uniform vec4 uMaterialColor;
uniform vec3 uSkyGradient;
uniform float uSaturation;
uniform vec2 uTexelSize;

vec3 hsb2rgb( in vec3 c ){
    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                             6.0)-3.0)-1.0,
                     0.0,
                     1.0 );
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix( vec3(1.0), rgb, c.y);
}

void main() {
// uMaterialColor: rgb: hue1, hue2, angle
vec3 gradient = uMaterialColor.rgb;
vec3 grad1 = hsb2rgb(vec3(gradient.r, uSaturation, 1.0));
vec3 grad2 = hsb2rgb(vec3(gradient.g, uSaturation, 1.0));

vec2 fragDirection = normalize(gl_FragCoord.xy);
float theta = gradient.b * 3.141592;
vec2 gradientDir = vec2(cos(theta), sin(theta));
float lenSq = dot(gradientDir, gradientDir);
float t = dot(fragDirection, gradientDir) / lenSq;
gl_FragColor = vec4(mix(grad1, grad2, t), 1.0);
}
	///////////////////////////////
`
};

// === Tab: postShader ===
let postShaderCode = { // Normal-based sobel & brightness based cross hatch
	///////////////////////////////
	vert: `
precision highp float;
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
  vTexCoord = aTexCoord;
}
	`,
	///////////////////////////////
	frag: `
precision highp float;

uniform sampler2D uColorTex;
uniform sampler2D uDepthTex;
uniform sampler2D uNNNBTex;
uniform sampler2D uCrossHatchTex;
uniform vec2 uTexelSize;
uniform float uOutlineThreshold;
uniform vec4 uLineColor;
uniform int uShowDepthMap;

varying vec2 vTexCoord;

void sobel_edge(inout float _drawLine, sampler2D tex, vec2 coord, float diffThreshold)
{
	vec4 n[9];

	n[0] = texture2D(tex, coord + uTexelSize * vec2(-1.0, -1.0));
	n[1] = texture2D(tex, coord + uTexelSize * vec2( 0.0, -1.0));
	n[2] = texture2D(tex, coord + uTexelSize * vec2( 1.0, -1.0));
	n[3] = texture2D(tex, coord + uTexelSize * vec2(-1.0,  0.0));
	n[4] = texture2D(tex, coord);
	n[5] = texture2D(tex, coord + uTexelSize * vec2( 1.0, 0.0));
	n[6] = texture2D(tex, coord + uTexelSize * vec2(-1.0, 1.0));
	n[7] = texture2D(tex, coord + uTexelSize * vec2( 0.0, 1.0));
	n[8] = texture2D(tex, coord + uTexelSize * vec2( 1.0, 1.0));

	vec4 sobel_edge_h = n[2] + (2.0*n[5]) + n[8] - (n[0] + (2.0*n[3]) + n[6]);
	float diff_h = max(max(abs(sobel_edge_h.r),abs(sobel_edge_h.g)),abs(sobel_edge_h.b));
  vec4 sobel_edge_v = n[0] + (2.0*n[1]) + n[2] - (n[6] + (2.0*n[7]) + n[8]);
	float diff_v = max(max(abs(sobel_edge_v.r),abs(sobel_edge_v.g)),abs(sobel_edge_v.b));

	float sobel = sqrt((diff_h * diff_h) + (diff_v * diff_v));

	if (sobel > diffThreshold)
		_drawLine = 1.0;
}

void main() {
  float depth = texture2D(uDepthTex, vTexCoord).r;
	vec4 color = texture2D(uColorTex, vTexCoord);
	vec3 normal = texture2D(uNNNBTex, vTexCoord).xyz;

	float drawLine = 0.0;
	float drawShine = 0.0;

	sobel_edge(drawLine, uDepthTex, vTexCoord, uOutlineThreshold);
	sobel_edge(drawLine, uNNNBTex, vTexCoord, uOutlineThreshold);

	float brightness = texture2D(uNNNBTex, vTexCoord).a;
	vec2 evenSample = vec2(vTexCoord.x, vTexCoord.y * uTexelSize.x/uTexelSize.y);
	vec4 crosshatch = texture2D(uCrossHatchTex, fract(8.0*evenSample));
	if (brightness <= 0.1)
		drawLine = max(drawLine, crosshatch.g);
	if (brightness < 0.2)
		drawLine = max(drawLine, crosshatch.r);
	if (brightness < 0.3)
		drawLine = max(drawLine, crosshatch.b);
	if (brightness >= 1.0) 
		drawShine = 1.0;

	vec4 shineColor = vec4(1.0);
	gl_FragColor = mix(mix(color, shineColor, drawShine), uLineColor, drawLine);
	gl_FragColor.a = 1.0;
	if (uShowDepthMap == 1)
		gl_FragColor = vec4(depth, brightness, 0.0, 1.0);



}
	///////////////////////////////
`
};

// === Tab: nnnbShader ===
let nnnbShaderCode = { //Store normals as xyz, store brighntess as alpha
	///////////////////////////////
	vert: `
attribute vec3 aPosition;
attribute vec3 aNormal;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform vec3 uLightingDirection[5];

varying vec3 vNormal;
varying vec3 vLightDirection;

void main(void) {
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);

	vNormal = normalize(uNormalMatrix * aNormal);
	vLightDirection = -uLightingDirection[0];

  gl_Position = uProjectionMatrix * viewModelPosition;
}
	`,
	///////////////////////////////
	frag: `
precision highp float;

uniform vec4 uMaterialColor;
uniform float uSmoothness;
uniform vec3 uViewDir;

varying vec3 vNormal;
varying vec3 vLightDirection;


void main() {

	float alpha = uMaterialColor.a;

	vec3 normal = normalize(vNormal);
	vec3 lightDir = normalize(vLightDirection);
	float intensity = max(0.0, dot(lightDir, normal));

	vec3 reflectionDir = reflect(-lightDir, normal);
  float specular = clamp(dot(uViewDir, reflectionDir), 0.0, 1.0);
  specular = pow(specular, uSmoothness * 500.0);
	float brightness = 0.9*intensity + specular;

	vec3 normalColor = mix(vNormal, vec3(1.0), step(1.0, brightness));
	gl_FragColor = vec4(normalColor, brightness);
}
	///////////////////////////////
`
};

